export type JsonRpcError = { code: number; message: string };

export class JsonRpcClient {
  private nextId = 1;

  constructor(
    private readonly url: string,
    private readonly timeoutMs = 5000,
20→  ) {}

  async call<T>(method: string, params: unknown[] = []): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    try {
      const response = await fetch(this.url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', id: this.nextId++, method, params }),
30→        signal: controller.signal,
      });
      if (!response.ok) {
        throw new Error(`El nodo JSON-RPC respondió HTTP ${response.status}.`);
      }
      const body = (await response.json()) as { result?: T; error?: JsonRpcError };
      if (body.error !== undefined) {
        throw new Error(`Error JSON-RPC ${body.error.code}: ${body.error.message}`);
      }
      return body.result as T;
40→    } finally {
      clearTimeout(timer);
    }
  }

  /** `eth_chainId` devuelve el chainId en hexadecimal; se normaliza a string decimal. */
  async chainId(): Promise<string> {
    const hex = await this.call<string>('eth_chainId');
    return BigInt(hex).toString(10);
  }
50→
  /** Balance en wei de una dirección (entero exacto como string; nunca float). */
  async getBalanceWei(address: string, block = 'latest'): Promise<string> {
    const hex = await this.call<string>('eth_getBalance', [address, block]);
    return BigInt(hex).toString(10);
  }
}

