  | { status: 'UNREACHABLE'; reason: string; checkedAt: string };

/** Sonda del nodo configurado; nunca lanza (el health-check no debe caerse por el nodo). */
export async function probeChain(client: JsonRpcClient | null): Promise<ChainStatus> {
  if (client === null) return { status: 'NOT_CONFIGURED' };
  const checkedAt = new Date().toISOString();
  try {
    const chainId = await client.chainId();
70→    if (chainId !== CHAIN_ID) {
